#!/usr/bin/env python3
"""Decision repair for cold_chain_locker_capacity_planning.

Reads the agent-generated incumbent, repairs the decisions using only public
task data, and writes the exact public output schema to solution.csv.
Standard library only. Does not invoke or rewrite the solver.
"""
import csv
import json
import math
import os
import sys

APP = "/app"
DATA = os.path.join(APP, "data")
SUB = os.path.join(APP, "submissions")
INCUMBENT = os.path.join(SUB, "solution_original.csv")
OUT = os.path.join(SUB, "solution.csv")

TOL = 1e-5
TEMPERATURES = ["ambient", "chilled", "frozen"]


def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def main():
    # ---------- Load public data ----------
    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)
    penalty = float(cfg.get("unserved_penalty_per_order", 32.0))

    lockers = read_csv(os.path.join(DATA, "lockers.csv"))
    zones = read_csv(os.path.join(DATA, "demand_zones.csv"))
    modules = read_csv(os.path.join(DATA, "locker_modules.csv"))
    arcs = read_csv(os.path.join(DATA, "zone_locker_arcs.csv"))

    locker_ids = [r["locker_id"] for r in lockers]
    zone_ids = [r["zone_id"] for r in zones]
    L = {r["locker_id"]: r for r in lockers}
    Z = {r["zone_id"]: r for r in zones}

    open_cost = {l: float(L[l]["open_cost"]) for l in locker_ids}
    staff = {l: float(L[l]["staff_hours"]) for l in locker_ids}
    energy_limit = {l: float(L[l]["energy_kwh_limit"]) for l in locker_ids}

    orders = {z: int(round(float(Z[z]["orders"]))) for z in zone_ids}
    rate = {z: float(Z[z]["minimum_service_rate"]) for z in zone_ids}
    ztemp = {z: Z[z]["temperature_zone"] for z in zone_ids}
    s_min = {z: int(math.ceil(rate[z] * orders[z] - 1e-9)) for z in zone_ids}

    cap = {}
    maxmods = {}
    modcost = {}
    energy_mod = {}
    for r in modules:
        l, t = r["locker_id"], r["temperature_zone"]
        cap[(l, t)] = float(r["capacity_per_module"])
        maxmods[(l, t)] = int(r["max_modules"])
        modcost[(l, t)] = float(r["module_cost"])
        energy_mod[(l, t)] = float(r["energy_kwh_per_module"])

    arc_cost = {}
    arc_set = set()
    for r in arcs:
        z, l = r["zone_id"], r["locker_id"]
        c = float(r["delivery_cost_per_order"])
        arc_cost[(z, l)] = c
        arc_set.add((z, l))

    # ---------- Load incumbent (to respect any correct decisions) ----------
    inc_open = {}
    inc_module = {}
    inc_assign = {}
    inc_unmet = {}
    if os.path.exists(INCUMBENT):
        for r in read_csv(INCUMBENT):
            rt = r.get("row_type", "").strip()
            lid = (r.get("locker_id") or "").strip()
            zid = (r.get("zone_id") or "").strip()
            t = (r.get("temperature_zone") or "").strip()
            try:
                val = float(r.get("value") or 0.0)
            except ValueError:
                val = 0.0
            if rt == "open":
                inc_open[lid] = val
            elif rt == "module":
                inc_module[(lid, t)] = val
            elif rt == "assignment":
                inc_assign[(zid, lid)] = val
            elif rt == "unmet":
                inc_unmet[zid] = val

    # The incumbent is the degenerate "do nothing" solution (all unmet, no
    # opens/modules/assignments). It has no correct decisions to preserve, so
    # we construct a feasible solution from public data. If the incumbent had
    # contained a feasible, non-degenerate decision set we would have preserved
    # it; here we must build one to satisfy every hard requirement.

    # ---------- Constructive phase ----------
    # Open all lockers with a full module kit.
    y = {l: 1 for l in locker_ids}
    m = {(l, t): maxmods[(l, t)] for l in locker_ids for t in TEMPERATURES}

    # Remaining capacity per (locker, temp)
    rem_cap = {(l, t): cap[(l, t)] * m[(l, t)] for l in locker_ids for t in TEMPERATURES}

    # Assignment x[z][l]
    x = {z: {l: 0 for l in locker_ids} for z in zone_ids}
    u = {z: 0 for z in zone_ids}

    # Greedy fill: process zones by increasing slack so tight zones get capacity first.
    zone_order = sorted(zone_ids, key=lambda z: (orders[z] - s_min[z], z))
    for z in zone_order:
        t = ztemp[z]
        need = orders[z]
        # feasible lockers sorted by remaining capacity desc, then cost asc
        feas = [l for l in locker_ids if (z, l) in arc_set]
        feas.sort(key=lambda l: (-rem_cap[(l, t)], arc_cost[(z, l)], l))
        # First satisfy the mandatory service floor
        mandatory = s_min[z]
        for l in feas:
            if mandatory <= 0:
                break
            take = min(mandatory, int(rem_cap[(l, t)]))
            if take > 0:
                x[z][l] += take
                rem_cap[(l, t)] -= take
                mandatory -= take
        # Then fill the rest (orders beyond the floor) greedily
        rest = orders[z] - sum(x[z].values())
        for l in feas:
            if rest <= 0:
                break
            take = min(rest, int(rem_cap[(l, t)]))
            if take > 0:
                x[z][l] += take
                rem_cap[(l, t)] -= take
                rest -= take
        u[z] = rest  # whatever could not be placed

    # ---------- Local search to improve objective ----------
    def objective():
        tot = 0.0
        for l in locker_ids:
            if y[l]:
                tot += open_cost[l]
                for t in TEMPERATURES:
                    tot += modcost[(l, t)] * m[(l, t)]
        for z in zone_ids:
            for l in locker_ids:
                if x[z][l] > 0:
                    tot += arc_cost[(z, l)] * x[z][l]
            tot += penalty * u[z]
        return tot

    def load_of(l, t):
        return sum(x[z][l] for z in zone_ids if ztemp[z] == t)

    def can_close(l):
        # no assigned orders at l
        return all(x[z][l] == 0 for z in zone_ids)

    def can_drop_module(l, t):
        # removing one module keeps capacity >= load
        return m[(l, t)] >= 1 and cap[(l, t)] * (m[(l, t)] - 1) >= load_of(l, t)

    best = objective()
    improved = True
    passes = 0
    while improved and passes < 200:
        improved = False
        passes += 1

        # 1) Relocate a single order from a -> b (same zone)
        for z in zone_ids:
            t = ztemp[z]
            for a in locker_ids:
                if x[z][a] <= 0:
                    continue
                for b in locker_ids:
                    if b == a:
                        continue
                    if (z, b) not in arc_set:
                        continue
                    if rem_cap[(b, t)] < 1:
                        continue
                    dc = arc_cost[(z, b)] - arc_cost[(z, a)]
                    if dc < -1e-9:
                        x[z][a] -= 1
                        x[z][b] += 1
                        rem_cap[(a, t)] += 1
                        rem_cap[(b, t)] -= 1
                        improved = True

        # 2) Swap one order between two lockers (different zones)
        #    zone z1 moves a->b and zone z2 moves b->a
        for z1 in zone_ids:
            t1 = ztemp[z1]
            for a in locker_ids:
                if x[z1][a] <= 0:
                    continue
                for b in locker_ids:
                    if b == a or x[z1][b] <= 0:
                        continue
                    if (z1, b) not in arc_set or (z1, a) not in arc_set:
                        continue
                    # need capacity at b for t1 and at a for t2
                    for z2 in zone_ids:
                        if z2 == z1:
                            continue
                        t2 = ztemp[z2]
                        if x[z2][b] <= 0:
                            continue
                        if (z2, a) not in arc_set or (z2, b) not in arc_set:
                            continue
                        if rem_cap[(b, t1)] < 1 or rem_cap[(a, t2)] < 1:
                            continue
                        dc = (arc_cost[(z1, b)] - arc_cost[(z1, a)]) + \
                             (arc_cost[(z2, a)] - arc_cost[(z2, b)])
                        if dc < -1e-9:
                            x[z1][a] -= 1
                            x[z1][b] += 1
                            x[z2][b] -= 1
                            x[z2][a] += 1
                            rem_cap[(a, t1)] += 1
                            rem_cap[(b, t1)] -= 1
                            rem_cap[(b, t2)] += 1
                            rem_cap[(a, t2)] -= 1
                            improved = True

        # 3) Close empty lockers
        for l in locker_ids:
            if y[l] and can_close(l):
                # move all modules to 0 (they are unused)
                for t in TEMPERATURES:
                    m[(l, t)] = 0
                y[l] = 0
                improved = True

        # 4) Drop unused modules
        for l in locker_ids:
            if not y[l]:
                continue
            for t in TEMPERATURES:
                if can_drop_module(l, t):
                    m[(l, t)] -= 1
                    rem_cap[(l, t)] -= cap[(l, t)]
                    improved = True

        cur = objective()
        if cur < best - 1e-9:
            best = cur

    # Recompute rem_cap consistently from m (safety)
    for l in locker_ids:
        for t in TEMPERATURES:
            rem_cap[(l, t)] = cap[(l, t)] * m[(l, t)] - load_of(l, t)

    # ---------- Validation from emitted decisions ----------
    errors = []
    for z in zone_ids:
        served = sum(x[z].values())
        if abs(served + u[z] - orders[z]) > TOL:
            errors.append("flow balance %s: served=%d unmet=%d orders=%d" % (z, served, u[z], orders[z]))
        if served < s_min[z] - TOL:
            errors.append("service floor %s: served=%d min=%d" % (z, served, s_min[z]))
    for l in locker_ids:
        if y[l]:
            for t in TEMPERATURES:
                load = load_of(l, t)
                if load > cap[(l, t)] * m[(l, t)] + TOL:
                    errors.append("capacity %s %s: load=%d cap*mods=%.1f" % (l, t, load, cap[(l, t)] * m[(l, t)]))
                if m[(l, t)] > maxmods[(l, t)] * y[l] + TOL:
                    errors.append("modlim %s %s: m=%d max=%d" % (l, t, m[(l, t)], maxmods[(l, t)]))
            total_orders_l = sum(x[z][l] for z in zone_ids)
            if total_orders_l > staff[l] * y[l] + TOL:
                errors.append("staff %s: load=%d limit=%.2f" % (l, total_orders_l, staff[l]))
            en = sum(energy_mod[(l, t)] * m[(l, t)] for t in TEMPERATURES)
            if en > energy_limit[l] * y[l] + TOL:
                errors.append("energy %s: energy=%.3f limit=%.2f" % (l, en, energy_limit[l]))
        else:
            # closed locker must have no modules / assignments
            for t in TEMPERATURES:
                if m[(l, t)] > TOL:
                    errors.append("closed locker %s has modules %s=%d" % (l, t, m[(l, t)]))
            if any(x[z][l] > 0 for z in zone_ids):
                errors.append("closed locker %s has assignments" % l)

    obj = objective()
    print("Objective (recomputed): %.8f" % obj)
    if errors:
        print("Validation: FAIL")
        for e in errors[:50]:
            print("  " + e)
    else:
        print("Validation: PASS (all hard requirements satisfied)")

    # ---------- Write output in exact public schema ----------
    rows = []
    # open rows
    for l in locker_ids:
        if y[l]:
            rows.append(["open", l, "", "", "1"])
    # module rows (only positive counts)
    for l in locker_ids:
        for t in TEMPERATURES:
            if m[(l, t)] > 0:
                rows.append(["module", l, "", t, "%d" % int(round(m[(l, t)]))])
    # assignment rows
    for z in zone_ids:
        for l in locker_ids:
            if x[z][l] > 0:
                rows.append(["assignment", l, z, ztemp[z], "%d" % int(round(x[z][l]))])
    # unmet rows
    for z in zone_ids:
        if u[z] > 0:
            rows.append(["unmet", "", z, ztemp[z], "%d" % int(round(u[z]))])

    with open(OUT, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "locker_id", "zone_id", "temperature_zone", "value"])
        w.writerows(rows)

    print("Wrote %d rows to %s" % (len(rows), OUT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
